'use strict';
// Requested additions are isolated from WORDS and the syllabus mock quiz.
const EXTRA_PRACTICE=[
  {id:'extra-time',kana:'なんじ',en:'what time',zh:'幾點',added:true},
  {id:'extra-price',kana:'いくら',en:'how much (price)',zh:'多少錢',added:true},
  {id:'extra-begin',kana:'はじめましょう',en:"let’s begin",zh:'開始吧',added:true}
];
const questionWords=[
  {word:'1-19a',meaning:'How old? (standard form)',clue:'Ask a person’s age using the standard form.'},
  {word:'1-19b',meaning:'How old? (polite form)',clue:'Ask a person’s age using the polite alternative.'},
  {word:'1-17a',meaning:'Who? (standard form)',clue:'Ask who a person is using the standard form.'},
  {word:'1-17b',meaning:'Who? (polite form)',clue:'Ask who a person is using the polite alternative.'},
  {word:'2-36',meaning:'What? (before です)',clue:'Ask what something is. Choose the question word used before です.'},
  {extra:'extra-time',meaning:'What time?',clue:'You want to know the clock time, rather than someone’s age.'},
  {extra:'extra-price',meaning:'How much? (price)',clue:'You want to know the price of an item.'}
];
const demonstrativeWords=[
  {word:'2-01',meaning:'This · near the speaker · stands alone',clue:'The book is beside you. Refer to it with a word that stands alone.'},
  {word:'2-02',meaning:'That · near the listener · stands alone',clue:'The book is beside the person you are speaking to. Use a word that stands alone.'},
  {word:'2-03',meaning:'That over there · far from both · stands alone',clue:'The book is far from both of you. Use a word that stands alone.'},
  {word:'2-04',meaning:'This … · near the speaker · before a noun',clue:'The book is beside you. Choose the word that goes immediately before the noun “book”.'},
  {word:'2-05',meaning:'That … · near the listener · before a noun',clue:'The book is beside the listener. Choose the word that goes immediately before a noun.'},
  {word:'2-06',meaning:'That … over there · far from both · before a noun',clue:'The book is far from both of you. Choose the word that goes immediately before a noun.'},
  {word:'2-c1',meaning:'Um / excuse me … · get someone’s attention',clue:'You hesitate and politely get someone’s attention before speaking. This is an expression, rather than a word pointing to an object.'}
];
function matchingItems(kind){return (kind==='wh'?questionWords:demonstrativeWords).map(q=>{const w=q.word?wordBy(q.word):EXTRA_PRACTICE.find(x=>x.id===q.extra);const explanations={
  '1-19a':'なんさい asks age in the standard form. なんじ asks about clock time.',
  '1-19b':'おいくつ is the polite age question. The standard form is なんさい.',
  '1-17a':'だれ asks who someone is. どなた is the polite alternative.',
  '1-17b':'どなた is the polite alternative to だれ.',
  '2-36':'なん means “what” in the taught pattern なんですか.',
  'extra-time':'なんじ asks for the clock time. It is different from なんさい, which asks age.',
  'extra-price':'いくら asks how much something costs.',
  '2-01':'これ stands alone and refers to something near the speaker. この must come before a noun.',
  '2-02':'それ stands alone and refers to something near the listener. その must come before a noun.',
  '2-03':'あれ stands alone and refers to something far from both people. あの must come before a noun.',
  '2-04':'この comes directly before a noun and points to something near the speaker.',
  '2-05':'その comes directly before a noun and points to something near the listener.',
  '2-06':'あの comes directly before a noun and points to something far from both people. あのう gets attention.',
  '2-c1':'あのう gets attention or shows hesitation. The final う distinguishes it from the noun modifier あの.'
};return {...q,id:`${kind}-${w.id}`,kana:w.kana,zh:w.zh,added:!!w.added,why:explanations[w.id]};});}
const DIALOGUES=[
  {id:'meet',word:'1-c1',family:'first-meeting',scene:'You meet someone for the first time.',speaker:'You',line:'Nice to meet you.',why:'はじめまして is the opening expression for a first meeting.'},
  {id:'intro',word:'1-c3d',family:'introduction',scene:'You have just introduced yourself. Finish with the full polite expression.',speaker:'You',line:'Pleased to meet you. Please treat me kindly.',why:'どうぞよろしくおねがいします is the full introduction expression on your page.'},
  {id:'likewise',word:'2-d2c',family:'likewise',scene:'Someone has finished an introduction with よろしくおねがいします. Give the polite “likewise” reply.',speaker:'You',line:'The pleasure is mine. Pleased to meet you too.',why:'こちらこそ responds to the other person’s greeting. Here it precedes よろしくおねがいします.'},
  {id:'excuse',word:'1-c4',family:'excuse',scene:'You are about to ask a stranger their name. Begin with an apologetic introduction to the question.',speaker:'You',line:'Excuse me, but …',why:'しつれいですが politely introduces a personal question.'},
  {id:'name',word:'1-c5',family:'name',scene:'You have politely got someone’s attention and now ask their name.',speaker:'You',line:'Your name, please?',why:'おなまえは is the short name question supplied in Chapter 1. は remains the particle は.'},
  {id:'attention',word:'2-c1',family:'attention',scene:'You hesitate before politely attracting someone’s attention.',speaker:'You',line:'Um / excuse me …',why:'あのう is a hesitation or attention-getting expression. It has a final う.'},
  {id:'offer',word:'2-c3',family:'offer',scene:'You hand someone a pen.',speaker:'You',line:'Here you are.',why:'どうぞ is used when offering something or inviting someone to do something.'},
  {id:'thanks',word:'2-c4c',family:'thanks',scene:'Someone hands you a gift. Thank them politely.',speaker:'You',line:'Thank you.',why:'ありがとうございます is a polite thank-you expression. Other thank-you variants are kept out of the choices for this question.'},
  {id:'thanks-full',word:'2-c4d',family:'thanks',scene:'Someone has helped you. Use the full thank-you expression from your page.',speaker:'You',line:'Thank you very much.',why:'どうもありがとうございます is the full expression with どうも.'},
  {id:'understand',word:'2-c5',family:'understand',scene:'Someone gives you new information. Show that you have understood.',speaker:'You',line:'I see.',why:'そうですか acknowledges what the other person has said.'},
  {id:'incorrect',word:'2-c6',family:'incorrect',scene:'Someone incorrectly identifies your book as a dictionary. Correct their statement.',speaker:'You',line:'That is not correct.',why:'ちがいます is the taught expression for correcting an incorrect statement.'},
  {id:'surprise',word:'2-c2',family:'surprise',scene:'You hear unexpected news and react with surprise.',speaker:'You',line:'Oh! / What?',why:'えっ expresses surprise. The small っ is part of the spelling.'},
  {id:'realise',word:'2-c7',family:'realisation',scene:'You suddenly notice that the umbrella is yours.',speaker:'You',line:'Ah!',why:'あ is the short reaction used when you realise something.'},
  {id:'neighbour',word:'2-d1',family:'neighbour',scene:'You introduce yourself to a new neighbour and use the fixed expression from the dialogue.',speaker:'You',line:'I look forward to your kindness.',why:'これからおせわになります is a fixed expression from the Chapter 2 dialogue.'},
  {id:'class-begin',extra:'extra-begin',family:'classroom',scene:'At the beginning of a class, the teacher addresses the students.',speaker:'Teacher',line:'Let’s begin.',why:'はじめましょう means “Let’s begin.” This classroom expression was added at your request.'}
];
function dialogueItems(scope='all'){return DIALOGUES.filter(d=>scope!=='quiz'||!d.extra).map(d=>{const w=d.word?wordBy(d.word):EXTRA_PRACTICE.find(w=>w.id===d.extra);return {...d,kana:w.kana,added:!!d.extra};});}
function kanaUnits(text){const units=[];for(const c of [...text]){if(/[ゃゅょぁぃぅぇぉゎ]/u.test(c)&&units.length)units[units.length-1]+=c;else units.push(c);}return units;}
function activityNav(){if(state.view==='match'||state.view==='matching')return 'matching';if(state.view==='activity')return state.activity?.kind.startsWith('dialogue')?'dialogue':'matching';return state.view;}
function activityCard(title,copy,label,attr,tone=''){return `<button class="mode-card ${tone}" ${attr}><span class="eyebrow muted">${label}</span><h2>${title}</h2><p>${copy}</p><span class="mode-link">Start practice ${icon('arrow')}</span></button>`;}
function matchingMenu(){return header('Matching, your way.','Choose a group. Get feedback after each answer and return to missed items at the end.')+`<section class="mode-grid">${activityCard('Kanji match','Match readings with their taught kanji. Only kanji-bearing words and choices are included.',`${WORDS.filter(hasKanji).length} WORDS`,'data-open-match="kanji"')}${activityCard('Question words','Choose among age, person, time, price and “what” questions. Standard and polite forms have distinct prompts.','7 WORDS · 2 REQUESTED ADDITIONS','data-open-match="wh"','mode-yellow')}${activityCard('This, that & attention','Tell これ・それ・あれ apart from この・その・あの, and practise the attention-getter あのう.','7 WORDS · QUIZ VOCABULARY','data-open-match="demonstratives"','mode-blue')}</section><div class="info-box" style="margin-top:23px">なんじ and いくら were added at your request. They appear in Question Words practice and are excluded from the Chapters 1–2 mock quiz.</div>`;}
function dialogueMenu(){return header('Practise the conversation.','Read the scene, then give the Japanese for the highlighted English line. You can choose a whole expression or build it in hiragana.')+`<label class="field-label" for="dialogue-scope">EXPRESSION SELECTION</label><select class="filter" id="dialogue-scope" data-dialogue-scope>${options([['all','Quiz expressions + your classroom example'],['quiz','Quiz-page expressions only']],state.dialogueScope)}</select><section class="mode-grid two-modes" style="margin-top:24px">${activityCard('Choose an expression','Read the situation and pick the appropriate Japanese expression from four choices.',`${dialogueItems(state.dialogueScope).length} SCENES`,'data-open-dialogue="dialogue-choice"')}${activityCard('Build with hiragana','Tap the hiragana units in order. Combinations with small kana stay together: は・じ・め・ま・しょ・う.','HIRAGANA TILE PRACTICE','data-open-dialogue="dialogue-tiles"','mode-yellow')}</section><div class="info-box" style="margin-top:23px">はじめましょう is your requested classroom addition. The “Quiz-page expressions only” selection leaves it out. The regular mock quiz continues to use its original Chapters 1–2 bank.</div>`;}
function startActivity(kind,ids){const dialogue=kind.startsWith('dialogue');const items=dialogue?dialogueItems(state.dialogueScope):matchingItems(kind);state.activity={kind,items,ids:ids||shuffle(items.map(x=>x.id)),index:0,correct:0,missed:[],checked:false,selected:null,chosen:[],tileBank:[],choices:[],result:false};state.view='activity';prepareActivity();render();window.scrollTo({top:0,behavior:'smooth'});}
function activityCurrent(){const a=state.activity;return a?.items.find(x=>x.id===a.ids[a.index]);}
function prepareActivity(){const a=state.activity,q=activityCurrent();if(!q)return;a.checked=false;a.selected=null;a.chosen=[];a.result=false;const dialogue=a.kind.startsWith('dialogue');const candidates=shuffle(a.items.filter(x=>x.id!==q.id&&(!dialogue||x.family!==q.family)));a.choices=shuffle([q,...candidates.slice(0,3)]);if(a.kind==='dialogue-tiles'){const correct=kanaUnits(q.kana),other=[...new Set(a.items.flatMap(x=>kanaUnits(x.kana)))].filter(x=>!correct.includes(x));a.tileBank=shuffle([...correct,...shuffle(other).slice(0,3)]);}}
function activityAnswer(){const a=state.activity;return a.chosen.map(id=>a.tileBank[id]).join('');}
function checkActivity(choice=null){const a=state.activity,q=activityCurrent();if(!q||a.checked)return;const tiles=a.kind==='dialogue-tiles';if(!tiles&&!a.choices.some(c=>c.id===choice))return;a.selected=choice;a.result=tiles?activityAnswer()===q.kana:choice===q.id;a.checked=true;if(a.result)a.correct++;else if(!a.missed.includes(q.id))a.missed.push(q.id);record('activities',`${a.kind}-${q.id}`,a.result);render();}
function activityPage(){const a=state.activity;if(!a)return matchingMenu();const dialogue=a.kind.startsWith('dialogue');const menu=dialogue?'dialogue':'matching';if(a.index>=a.ids.length)return header('Round complete.','Give yourself another chance with the items you missed.')+`<div class="study-wrap paper result-center"><div class="result-score">${a.correct}<small> / ${a.ids.length}</small></div><p class="muted" style="margin-top:15px">${a.missed.length?`${a.missed.length} items are ready for another look.`:'Every answer correct in this round.'}</p><div class="card-actions">${a.missed.length?button('Practise missed items','activityMissed','coral'):''}${button('New round','activityRestart','primary')}<button class="button ghost" data-view="${menu}">Back to menu</button></div></div>`;
const q=activityCurrent(),tileMode=a.kind==='dialogue-tiles',title=dialogue?'Your next line.':a.kind==='wh'?'Which question word?':'Choose the right word.';
return header(title,dialogue?'Give the Japanese for the highlighted line.':q.clue)+`<section class="study-wrap"><div class="row between" style="margin-bottom:17px"><button class="scope-link" data-view="${menu}">← Back to menu</button><span class="pill">${a.index+1} / ${a.ids.length} · ${a.correct} correct</span></div><div class="progress-bar"><div class="progress-fill" style="width:${100*a.index/a.ids.length}%"></div></div><section class="paper">${q.added?'<span class="pill added-pill">Added at your request</span>':'<span class="eyebrow muted">QUIZ-PAGE VOCABULARY</span>'}${dialogue?`<p class="dialogue-scene">${esc(q.scene)}</p><div class="dialogue-bubble"><span class="eyebrow">${esc(q.speaker)} · LINE TO SAY</span><p>“${esc(q.line)}”</p></div>`:`<h2 class="meaning-prompt">${esc(q.meaning)}</h2>`}${tileMode?activityTiles(q):activityChoices()}${a.checked?`<div class="feedback ${a.result?'':'bad'}" role="status"><strong>${a.result?'Correct!':'The correct answer is:'}</strong><div class="jp" lang="ja">${esc(q.kana)}</div><p>${esc(q.why||q.clue)}</p>${tileMode?`<p class="small jp">${kanaUnits(q.kana).map(esc).join(' · ')}</p>`:''}</div><div class="card-actions">${button('Next '+icon('arrow'),'activityNext','primary')}</div>`:''}</section></section>`;}
function activityChoices(){const a=state.activity;return `<div class="options activity-options">${a.choices.map((q,i)=>`<button class="option jp ${a.checked&&q.id===activityCurrent().id?'correct':a.checked&&q.id===a.selected?'wrong':''}" data-activity-choice="${q.id}" ${a.checked?'disabled':''}><span class="number">${i+1}</span>${esc(q.kana)}</button>`).join('')}</div>`;}
function activityTiles(q){const a=state.activity,limit=kanaUnits(q.kana).length;return `<p class="small muted" style="margin-top:22px">Tap hiragana in order. Tap a placed tile to undo it. There are extra tiles in the bank.</p><div class="token-area ${a.chosen.length?'filled':''}" aria-label="Your hiragana answer">${a.chosen.length?a.chosen.map((id,i)=>`<button class="tile jp" data-activity-return="${i}" ${a.checked?'disabled':''}>${esc(a.tileBank[id])}</button>`).join(''):'<span class="empty-hint">Build the Japanese expression here.</span>'}</div><div class="token-bank activity-tile-bank" aria-label="Hiragana bank">${a.tileBank.map((unit,i)=>`<button class="tile jp" data-activity-tile="${i}" ${a.checked||a.chosen.includes(i)?'disabled':''}>${esc(unit)}</button>`).join('')}</div><div class="small muted">${a.chosen.length} / ${limit} units</div>${a.checked?'':`<div class="card-actions">${button('Clear','activityClear','ghost')}${button('Undo','activityUndo','ghost',a.chosen.length?'':'disabled')}${button('Check answer','activityCheck','primary',a.chosen.length===limit?'':'disabled')}</div>`}`;}
function activityAction(action){const a=state.activity;if(!a)return;switch(action){case'activityNext':a.index++;prepareActivity();render();break;case'activityRestart':startActivity(a.kind);break;case'activityMissed':startActivity(a.kind,shuffle(a.missed));break;case'activityClear':if(!a.checked)a.chosen=[];render();break;case'activityUndo':if(!a.checked)a.chosen.pop();render();break;case'activityCheck':checkActivity();break;}}
function activityClick(target){const d=target.dataset;if(d.openMatch){if(d.openMatch==='kanji')navigate('match');else startActivity(d.openMatch);return true;}if(d.openDialogue){startActivity(d.openDialogue);return true;}if(d.activityChoice){checkActivity(d.activityChoice);return true;}if(d.activityTile!==undefined){const a=state.activity;if(!a||a.checked)return true;const i=Number(d.activityTile),limit=kanaUnits(activityCurrent().kana).length;if(Number.isInteger(i)&&i>=0&&i<a.tileBank.length&&!a.chosen.includes(i)&&a.chosen.length<limit)a.chosen.push(i);render();return true;}if(d.activityReturn!==undefined){const a=state.activity;if(a&&!a.checked)a.chosen.splice(Number(d.activityReturn),1);render();return true;}if(d.action?.startsWith('activity')){activityAction(d.action);return true;}return false;}
